<template>
  <div class="mobile-page">
    <div class="mobile-head"><button class="back-button" @click="$router.back()">‹</button><div><b>县级计划管理</b><span>市级下达计划、县级分解与本级上报</span></div></div>
    <section v-if="activeTab === 'issued'" class="list-card">
      <div class="section-title"><div><b>市级下达给本县的计划</b><small>可查看并分解到乡镇</small></div><el-tag size="small" type="info">{{ plans.length }} 条</el-tag></div>
      <div v-for="item in plans" :key="item.id" class="plan-card"><div class="plan-main"><b>{{ item.year }}年{{ item.quarter }} · {{ item.cropType }}</b><p>{{ Number(item.area || 0).toLocaleString() }} 亩 · {{ item.description }}</p><small>已分解乡镇：{{ decompositionFor(item).length }} 个</small></div><el-button size="small" type="primary" @click="openDecompose(item)">分解到乡镇</el-button></div>
      <el-empty v-if="!plans.length" description="暂无市级下达计划" :image-size="55" />
    </section>

    <section v-if="activeTab === 'own'" class="list-card">
      <div class="section-title"><div><b>县级上报计划</b><small>在皖政通内完成本级填报和提交</small></div><el-button size="small" type="primary" @click="startReport(plans[0])" :disabled="!plans.length">新增上报</el-button></div>
      <div v-for="item in ownReports" :key="item.id" class="report-card"><div><b>{{ item.year }}年{{ item.quarter }} · {{ item.cropType }}</b><p>上报面积 {{ Number(item.area || 0).toLocaleString() }} 亩</p><small>{{ item.status }} · {{ item.updatedAt || '待提交' }}</small></div><el-tag size="small" :type="statusType(item.status)">{{ item.status }}</el-tag></div>
      <el-empty v-if="!ownReports.length" description="暂无县级上报记录，请新增上报" :image-size="55" />
    </section>

    <section v-if="activeTab === 'audit'" class="list-card">
      <div class="section-title"><div><b>乡镇上报计划审核</b><small>审核本县乡镇提交的计划</small></div><el-tag size="small" type="warning">待审核 {{ pendingReports.length }} 条</el-tag></div>
      <div v-for="item in townReports" :key="item.id" class="report-card"><div><b>{{ item.townName }} · {{ item.year }}年{{ item.quarter }}</b><p>{{ item.cropType }} · 上报 {{ Number(item.area || 0).toLocaleString() }} 亩</p><small>{{ item.remark || '暂无填报说明' }}</small></div><div class="audit-actions"><el-tag size="small" :type="statusType(item.status)">{{ item.status }}</el-tag><el-button link type="primary" @click="viewTownReport(item)">查看详情</el-button></div></div>
      <el-empty v-if="!townReports.length" description="暂无乡镇上报计划" :image-size="55" />
    </section>

    <el-dialog v-model="decomposeVisible" title="分解到乡镇" width="94%" destroy-on-close>
      <template v-if="selectedPlan"><div class="dialog-context"><b>{{ selectedPlan.year }}年{{ selectedPlan.quarter }} · {{ selectedPlan.cropType }}</b><span>计划 {{ Number(selectedPlan.area || 0).toLocaleString() }} 亩</span></div><div v-for="row in townRows" :key="row.townCode" class="town-row"><div><b>{{ row.townName }}</b><small>{{ row.townCode }}</small></div><el-input-number v-model="row.targetArea" :min="0" :precision="1" controls-position="right" /></div><el-button class="full-button" plain @click="addTownRow">新增乡镇</el-button></template>
      <template #footer><el-button @click="decomposeVisible = false">取消</el-button><el-button type="primary" @click="saveDecompose">保存乡镇分解</el-button></template>
    </el-dialog>

    <el-dialog v-model="reportVisible" title="县级上报计划" width="94%" destroy-on-close>
      <template v-if="selectedPlan"><div class="dialog-context"><b>{{ selectedPlan.year }}年{{ selectedPlan.quarter }} · {{ selectedPlan.cropType }}</b><span>市级计划 {{ Number(selectedPlan.area || 0).toLocaleString() }} 亩</span></div><el-form label-position="top"><el-form-item label="县级上报面积（亩）"><el-input-number v-model="reportForm.area" :min="0" :precision="1" controls-position="right" style="width:100%" /></el-form-item><el-form-item label="填报说明"><el-input v-model="reportForm.remark" type="textarea" :rows="3" maxlength="120" show-word-limit /></el-form-item></el-form><el-alert title="县级上报计划在皖政通移动端完成，不跳转 PC 页面。" type="info" :closable="false" /></template>
      <template #footer><el-button @click="reportVisible = false">取消</el-button><el-button type="primary" @click="saveReport">保存草稿</el-button></template>
    </el-dialog>

    <el-dialog v-model="auditDetailVisible" title="乡镇上报计划详情" width="94%" destroy-on-close>
      <template v-if="selectedTownReport">
        <div class="detail-head"><div><b>{{ selectedTownReport.townName }} · {{ selectedTownReport.year }}年{{ selectedTownReport.quarter }}</b><small>{{ selectedTownReport.cropType }}</small></div><el-tag size="small" :type="statusType(selectedTownReport.status)">{{ selectedTownReport.status }}</el-tag></div>
        <el-descriptions :column="1" border class="detail-descriptions"><el-descriptions-item label="关联计划">{{ selectedTownReport.planId || '—' }}</el-descriptions-item><el-descriptions-item label="上报面积">{{ Number(selectedTownReport.area || 0).toLocaleString() }} 亩</el-descriptions-item><el-descriptions-item label="主体参考面积">{{ Number(selectedTownReport.subjectReferenceArea || 0).toLocaleString() }} 亩</el-descriptions-item><el-descriptions-item label="填报主体">{{ selectedTownReport.subjectName || '乡镇本级' }}</el-descriptions-item><el-descriptions-item label="填报说明">{{ selectedTownReport.remark || '—' }}</el-descriptions-item><el-descriptions-item label="提交时间">{{ selectedTownReport.submittedAt || '—' }}</el-descriptions-item></el-descriptions>
        <div class="subject-review-box"><div class="detail-section-title"><b>种植主体计划明细</b><el-tag size="small" type="info">{{ (selectedTownReport.subjectRows || []).length }} 个主体</el-tag></div><div v-for="row in selectedTownReport.subjectRows || []" :key="row.subjectId || row.subjectName" class="subject-review-row"><div><b>{{ row.subjectName || '未填写主体' }}</b><small>{{ row.owner || '负责人待补充' }} · {{ (row.plotIds || []).length }} 块地</small></div><strong>{{ Number(row.targetArea || 0).toLocaleString() }} 亩</strong></div><el-empty v-if="!(selectedTownReport.subjectRows || []).length" description="乡镇本次未填写种植主体计划明细" :image-size="45" /></div><div class="audit-detail-tip">请核对乡镇、周期、作物、上报面积、主体计划明细及填报说明后，再执行审核。</div>
      </template>
      <template #footer><el-button @click="auditDetailVisible = false">关闭</el-button><el-button v-if="selectedTownReport?.status === '待县级审核'" type="danger" plain @click="auditFromDetail(false)">退回</el-button><el-button v-if="selectedTownReport?.status === '待县级审核'" type="success" @click="auditFromDetail(true)">通过</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useUserStore } from '@/stores/user'
import { useRoute } from 'vue-router'
import { fetchIssuedPlantingPlans, fetchPlantingPlanCityTasks, savePlantingPlanCityTasks, fetchTownPlanReports, auditTownPlanReport, savePlantingPlan } from '@/api/gpm'
import { listTowns } from '@/mock/common/regions'
const userStore = useUserStore(); const route = useRoute(); const activeTab = computed(() => route.path.endsWith('wzt-county-report') ? 'own' : route.path.endsWith('wzt-county-audit') ? 'audit' : 'issued'); const plans = ref([]); const townReports = ref([]); const ownReports = ref([]); const selectedPlan = ref(null); const decomposeVisible = ref(false); const reportVisible = ref(false); const auditDetailVisible = ref(false); const selectedTownReport = ref(null); const townRows = ref([]); const reportForm = ref({ area: 0, remark: '' }); const decompositionMap = ref({})
const pendingReports = computed(() => townReports.value.filter(item => item.status === '待县级审核')); const statusType = status => ({ 草稿: 'info', 待县级审核: 'warning', 审核通过: 'success', 已驳回: 'danger' }[status] || 'info')
const decompositionFor = item => decompositionMap.value[item.id] || []
const load = async () => { plans.value = await fetchIssuedPlantingPlans(userStore.role, {}); townReports.value = await fetchTownPlanReports(userStore.role); ownReports.value = plans.value.map(item => ({ ...item, area: item.area || item.targetArea || 0, status: item.status === '已分解' ? '待审核' : '草稿', updatedAt: item.updatedAt || item.issuedAt || '' })); for (const plan of plans.value) decompositionMap.value[plan.id] = await fetchPlantingPlanCityTasks(plan.id, userStore.role) }
const openDecompose = async plan => { selectedPlan.value = plan; const saved = await fetchPlantingPlanCityTasks(plan.id, userStore.role); townRows.value = saved.length ? saved.map(x => ({ townCode: x.townCode, townName: x.townName, targetArea: Number(x.targetArea || 0) })) : listTowns(userStore.role.regionCode).map(x => ({ townCode: x.code, townName: x.name, targetArea: 0 })); decomposeVisible.value = true }
const addTownRow = () => townRows.value.push({ townCode: `custom-${Date.now()}`, townName: '新增乡镇', targetArea: 0 })
const saveDecompose = async () => { const result = await savePlantingPlanCityTasks(selectedPlan.value.id, townRows.value.map(x => ({ ...x, planId: selectedPlan.value.id, roleCode: 'county', regionCode: userStore.role.regionCode, countyCode: userStore.role.regionCode })), userStore.role); if (!result.success) return ElMessage.error(result.message); ElMessage.success('乡镇计划分解已保存'); decomposeVisible.value = false; await load() }
const startReport = plan => { if (!plan) return; selectedPlan.value = plan; reportForm.value = { area: Number(plan.area || 0), remark: '' }; reportVisible.value = true }
const saveReport = async () => { if (!selectedPlan.value || Number(reportForm.value.area) <= 0) return ElMessage.warning('请填写县级上报面积'); const result = await savePlantingPlan({ id: selectedPlan.value.id, year: selectedPlan.value.year, quarter: selectedPlan.value.quarter, cropType: selectedPlan.value.cropType, area: Number(reportForm.value.area), description: reportForm.value.remark || `${selectedPlan.value.year}年${selectedPlan.value.quarter}${selectedPlan.value.cropType}县级上报计划` }, userStore.role); if (!result.success) return ElMessage.error(result.message); ElMessage.success('县级上报计划草稿已保存'); reportVisible.value = false; await load() }
const viewTownReport = item => { selectedTownReport.value = item; auditDetailVisible.value = true }
const auditFromDetail = async approved => { if (selectedTownReport.value) await audit(selectedTownReport.value, approved) }
const audit = async (item, approved) => { let opinion = ''; try { if (approved) await ElMessageBox.confirm(`确认通过${item.townName}的乡镇上报计划吗？`, '审核确认'); else opinion = (await ElMessageBox.prompt('请填写退回意见', '退回计划', { inputType: 'textarea' })).value } catch { return } const result = await auditTownPlanReport(item.id, approved, opinion, userStore.role); if (!result.success) return ElMessage.error(result.message); auditDetailVisible.value = false; selectedTownReport.value = null; ElMessage.success(approved ? '已通过' : '已退回'); await load() }
onMounted(load)
</script>

<style lang="scss" scoped>
.mobile-page{min-height:100%;box-sizing:border-box;background:#f5f7fa;padding:14px;overflow-x:hidden}.mobile-head,.list-card{background:#fff;border-radius:14px;padding:15px;margin-bottom:12px}.mobile-head{display:flex;align-items:center;gap:8px;color:#1f3c68}.mobile-head>div{flex:1}.mobile-head b{display:block;font-size:19px}.mobile-head span{display:block;color:#667085;font-size:11px;margin-top:4px}.back-button{border:0;background:none;font-size:36px;line-height:1;padding:0 8px 4px 0}.page-tabs{display:flex;gap:8px;margin-bottom:12px}.page-tabs button{flex:1;border:1px solid #d9e2ec;background:#fff;border-radius:8px;padding:10px;color:#667085}.page-tabs button.active{border-color:#2d8c72;background:#eaf6f1;color:#176b58;font-weight:600}.section-title,.report-card,.plan-card,.town-row{display:flex;align-items:center;justify-content:space-between;gap:10px}.section-title{color:#243b5a;margin-bottom:10px}.section-title small{display:block;color:#98a2b3;font-size:11px;font-weight:400;margin-top:4px}.plan-card,.report-card,.town-row{border-top:1px solid #edf0f5;padding:12px 0}.plan-main,.report-card>div:first-child{flex:1;min-width:0}.plan-card b,.report-card b,.town-row b{color:#243b5a;font-size:13px}.plan-card p,.report-card p,.report-card small,.town-row small{display:block;color:#667085;font-size:11px;margin:5px 0 0}.report-card small,.town-row small{color:#98a2b3}.audit-actions{display:flex;align-items:center;gap:3px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end}.detail-head{display:flex;align-items:center;justify-content:space-between;padding:12px;background:#eaf6f1;border-radius:9px;color:#176b58}.detail-head b,.detail-head small{display:block}.detail-head small{margin-top:4px;color:#667085;font-size:11px}.detail-descriptions{margin-top:12px}.subject-review-box{margin-top:12px;padding:11px;border:1px solid #e5ebf2;border-radius:9px;background:#fbfdff}.detail-section-title{display:flex;align-items:center;justify-content:space-between;color:#243b5a;margin-bottom:6px}.subject-review-row{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #edf0f5;padding:9px 0}.subject-review-row b,.subject-review-row small{display:block}.subject-review-row b{color:#243b5a;font-size:12px}.subject-review-row small{margin-top:3px;color:#98a2b3;font-size:10px}.subject-review-row strong{color:#176b58;font-size:13px}.audit-detail-tip{margin-top:12px;padding:10px 12px;background:#fff8e8;border:1px solid #f5dfaa;border-radius:8px;color:#8a6116;font-size:12px;line-height:1.5}.dialog-context{display:flex;justify-content:space-between;gap:8px;padding:12px;background:#eaf6f1;border-radius:9px;color:#176b58}.dialog-context span{color:#667085;font-size:12px}.full-button{width:100%;margin-top:10px}.town-row :deep(.el-input-number){width:120px}
</style>